create table public.lessons (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,course_id uuid not null references public.courses(id) on delete cascade,title text not null check(char_length(trim(title)) between 2 and 200),material text,attachment_url text,scheduled_at timestamptz,is_published boolean not null default false,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));create index lessons_tenant_course_idx on public.lessons(tenant_id,course_id);alter table public.lessons enable row level security;revoke all on public.lessons from anon,authenticated;create policy lessons_select_tenant on public.lessons for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values('lessons.read','Read lessons','View lessons'),('lessons.create','Create lessons','Create lessons'),('lessons.update','Update lessons','Maintain lessons'),('lessons.delete','Delete lessons','Delete lessons') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'lessons.%' on conflict do nothing;
